import{_ as e,C as i,o as n,a as l,a3 as o,E as r}from"./chunks/framework.CkbYhqXo.js";const b=JSON.parse('{"title":"Установка","description":"Подробная инструкция по установке Stuzhik на Windows. Системные требования и способы установки.","frontmatter":{"description":"Подробная инструкция по установке Stuzhik на Windows. Системные требования и способы установки.","head":[["meta",{"name":"keywords","content":"stuzhik скачать, установить stuzhik, стужик, minecraft launcher download, системные требования"}]]},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),s={name:"guide/installation.md"};function u(d,a,h,c,p,q){const t=i("DownloadButton");return n(),l("div",null,[a[0]||(a[0]=o('<h1 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h1><h2 id="системные-требования" tabindex="-1">Системные требования <a class="header-anchor" href="#системные-требования" aria-label="Permalink to &quot;Системные требования&quot;">​</a></h2><h3 id="минимальные" tabindex="-1">Минимальные <a class="header-anchor" href="#минимальные" aria-label="Permalink to &quot;Минимальные&quot;">​</a></h3><ul><li><strong>RAM:</strong> 4GB (рекомендуется 8GB)</li><li><strong>Место на диске:</strong> 2GB + место под экземпляры</li><li><strong>ОС:</strong> Windows 10+</li></ul><h3 id="рекомендуемые" tabindex="-1">Рекомендуемые <a class="header-anchor" href="#рекомендуемые" aria-label="Permalink to &quot;Рекомендуемые&quot;">​</a></h3><ul><li><strong>RAM:</strong> 16GB</li><li><strong>Место на диске:</strong> SSD с 20GB свободного места</li><li><strong>GPU:</strong> Любая с поддержкой OpenGL 3.3+</li></ul><h2 id="скачать" tabindex="-1">Скачать <a class="header-anchor" href="#скачать" aria-label="Permalink to &quot;Скачать&quot;">​</a></h2>',7)),r(t),a[1]||(a[1]=o('<ol><li>Скачай установщик кнопкой выше</li><li>Запусти скачанный установщик</li><li>Следуй инструкциям установщика</li></ol><p>Сборок для macOS и Linux нет, и в ближайших планах их нет.</p><h2 id="обновление" tabindex="-1">Обновление <a class="header-anchor" href="#обновление" aria-label="Permalink to &quot;Обновление&quot;">​</a></h2><p>Stuzhik проверяет обновления автоматически при запуске и сам ставит найденную версию.</p><p>Настроить: Настройки → &quot;Общие&quot; → раздел &quot;Обновления приложения&quot;:</p><ol><li>&quot;Проверять обновления при запуске&quot; — выключи, если автообновление не нужно</li><li>&quot;Канал обновлений&quot; — &quot;Стабильный&quot; или &quot;Бета&quot;</li></ol><p>Проверить вручную — там же, строка &quot;Проверить сейчас&quot; → кнопка &quot;Проверить обновления&quot;. Можно и просто скачать новый установщик и запустить поверх старого: сборки, миры и настройки останутся.</p><h2 id="деинсталляция" tabindex="-1">Деинсталляция <a class="header-anchor" href="#деинсталляция" aria-label="Permalink to &quot;Деинсталляция&quot;">​</a></h2><p>Удаляется как обычная программа: Параметры Windows → Приложения → Stuzhik → Удалить.</p><p>Что уходит при удалении:</p><ul><li><strong>Всегда</strong> — служебное: кэш, логи, отчёты об ошибках, данные встроенного браузера, сохранённые входы в аккаунты (они лежат в диспетчере учётных данных Windows) и правило брандмауэра для Stuzhik Connect. Чтобы снять правило, Windows один раз попросит подтверждение администратора — только если правило было создано</li><li><strong>Только с галочкой</strong> &quot;Удалить также сборки и миры (все данные лаунчера)&quot; — сборки, миры, настройки, Java и файлы игры. Без галочки они остаются, и после повторной установки всё на месте</li></ul><p>Обновление лаунчера ничего из этого не трогает.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="не-запускается" tabindex="-1">Не запускается <a class="header-anchor" href="#не-запускается" aria-label="Permalink to &quot;Не запускается&quot;">​</a></h3><p>Установи <a href="https://developer.microsoft.com/en-us/microsoft-edge/webview2/" target="_blank" rel="noreferrer">WebView2 Runtime</a>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">winget</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> Microsoft.EdgeWebView2Runtime</span></span></code></pre></div>',16))])}const g=e(s,[["render",u]]);export{b as __pageData,g as default};
